WITH t AS (SELECT TIMESTAMP '2014-08-31 14:57' AS t),
rel AS (
  SELECT src, relation, dst FROM links_at((SELECT t FROM t))
),
rel_sec AS (
  SELECT CASE WHEN src='SEC-580' THEN dst ELSE src END AS other
  FROM rel WHERE relation='relates_to' AND (src='SEC-580' OR dst='SEC-580')
),
dep AS (
  SELECT src, dst FROM rel WHERE relation='depends_on'
),
second AS (
  SELECT DISTINCT CASE WHEN d.src = r.other THEN d.dst ELSE d.src END AS issue
  FROM rel_sec r JOIN dep d ON d.src = r.other OR d.dst = r.other
)
SELECT issue FROM second WHERE issue <> 'SEC-580' AND issue NOT IN (SELECT other FROM rel_sec) ORDER BY issue;

