  FROM recorded WHERE type = 'issue.created' AND occurred_at <= TIMESTAMP '2014-09-29 03:44'
),
changed AS (
  SELECT issue_key, occurred_at, payload->>'status' AS status, recorded_at,
         ROW_NUMBER() OVER (PARTITION BY issue_key ORDER BY occurred_at DESC, recorded_at DESC) rn
  FROM recorded WHERE type = 'issue.status_changed' AND occurred_at <= TIMESTAMP '2014-09-29 03:44'
)
