SELECT key, parent FROM issues WHERE key = 'TAJO-1891' OR parent = 'TAJO-1891';
SELECT src, relation, dst, valid_from, valid_to, recorded_at, superseded_at FROM links WHERE relation = 'depends_on' AND (src = 'TAJO-744' OR dst = 'TAJO-744') ORDER BY recorded_at;
SELECT src, relation, dst, valid_from, valid_to, recorded_at, superseded_at FROM links WHERE relation = 'subtask_of' AND (src = 'TAJO-744' OR dst = 'TAJO-744');

WITH a AS (
  SELECT issue_key, status FROM issue_state_at(TIMESTAMP '2014-03-19 21:05') WHERE status IN ('In Progress','Patch Available')
),
b AS (
  SELECT issue_key, status FROM issue_state_at(TIMESTAMP '2014-06-01 15:58') WHERE status IN ('In Progress','Patch Available')
)
SELECT a.issue_key, a.status AS status_mar19, b.status AS status_jun01
FROM a JOIN b ON a.issue_key = b.issue_key
ORDER BY a.issue_key;

SELECT SUM(date_diff('microsecond', valid_from, COALESCE(valid_to, TIMESTAMP '2020-05-15 05:30')) / 86400000000.0) AS days_current
FROM field_versions
WHERE issue_key = 'TAJO-1181' AND field = 'status' AND value = 'Patch Available' AND superseded_at IS NULL;

WITH l AS (
  SELECT src, dst FROM links_at(TIMESTAMP '2012-12-03 08:30') WHERE relation = 'relates_to'
),
d1 AS (
  SELECT CASE WHEN src = 'RAVE-27' THEN dst ELSE src END AS k
  FROM l WHERE src = 'RAVE-27' OR dst = 'RAVE-27'
),
d2 AS (
  SELECT DISTINCT CASE WHEN l.src = d1.k THEN l.dst ELSE l.src END AS k
  FROM l JOIN d1 ON (l.src = d1.k OR l.dst = d1.k)
)
SELECT DISTINCT k FROM d2 WHERE k <> 'RAVE-27' AND k NOT IN (SELECT k FROM d1) ORDER BY k;

SELECT src, relation, dst, valid_from, valid_to, recorded_at, superseded_at FROM links
WHERE relation = 'depends_on' AND (src = 'TAJO-16' OR dst = 'TAJO-16')
